package com.arcvision.arcledger.data.dao; import android.content.*; import android.database.Cursor; import com.arcvision.arcledger.data.db.DatabaseHelper; import com.arcvision.arcledger.data.model.AppSettings; public class SettingsDao {private final DatabaseHelper h; public SettingsDao(Context c){h=new DatabaseHelper(c);} public AppSettings getSettings(){Cursor c=h.getReadableDatabase().rawQuery("SELECT * FROM app_settings ORDER BY id LIMIT 1",null);AppSettings s=new AppSettings();if(c.moveToFirst()){s.id=c.getLong(0);s.businessName=c.getString(1);s.ownerName=c.getString(2);s.currency=c.getString(3);}c.close();return s;} public int updateSettings(AppSettings s){ContentValues v=new ContentValues();v.put("business_name",s.businessName);v.put("owner_name",s.ownerName);v.put("currency",s.currency);v.put("updated_at",s.updatedAt);return h.getWritableDatabase().update("app_settings",v,"id=?",new String[]{String.valueOf(s.id)});} }
